import { MakeLogicType, actions, connect, kea, listeners, path, selectors } from 'kea'
import posthog from 'posthog-js'

import { teamLogic } from 'scenes/teamLogic'

import { TeamPublicType, TeamType } from '~/types'

// pinned: sent as the `surface` property of `audience engagement events enabled`
export type TurnOnEngagementEventsSurface = 'engagement' | 'recipient' | 'setup'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface engagementEventsLogicValues {
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    currentTeamLoading: boolean // teamLogic
    engagementEventsCaptured: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface engagementEventsLogicActions {
    setEngagementEventsCapture: (enabled: boolean) => {
        enabled: boolean
    }
    turnOnEngagementEvents: (surface: TurnOnEngagementEventsSurface) => {
        surface: TurnOnEngagementEventsSurface
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface engagementEventsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        engagementEventsCaptured: (currentTeam: TeamPublicType | TeamType | null) => boolean
    }
}

export type engagementEventsLogicType = MakeLogicType<
    engagementEventsLogicValues,
    engagementEventsLogicActions,
    Record<string, any>,
    engagementEventsLogicMeta
>

export const engagementEventsLogic = kea<engagementEventsLogicType>([
    path(['products', 'workflows', 'frontend', 'engagementEventsLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeam', 'currentTeamLoading']],
    })),
    actions({
        turnOnEngagementEvents: (surface: TurnOnEngagementEventsSurface) => ({ surface }),
        setEngagementEventsCapture: (enabled: boolean) => ({ enabled }),
    }),
    selectors({
        engagementEventsCaptured: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): boolean =>
                !!currentTeam?.workflows_config?.capture_workflows_engagement_events,
        ],
    }),
    listeners(({ values }) => {
        const saveEngagementEventsCapture = async (enabled: boolean): Promise<boolean> => {
            await teamLogic.asyncActions.updateCurrentTeam({
                workflows_config: { capture_workflows_engagement_events: enabled },
            })
            return values.engagementEventsCaptured === enabled
        }

        return {
            turnOnEngagementEvents: async ({ surface }) => {
                if (await saveEngagementEventsCapture(true)) {
                    // pinned: event name is a wire string
                    posthog.capture('audience engagement events enabled', { surface })
                }
            },
            setEngagementEventsCapture: async ({ enabled }) => {
                if (await saveEngagementEventsCapture(enabled)) {
                    // pinned: event name is a wire string
                    posthog.capture('workflows engagement events toggled', { enabled, surface: 'settings' })
                }
            },
        }
    }),
])
